};

/**
 * Animates text content character by character with varying delays
 * @param {HTMLElement} element - The element containing text to animate
 * @param {Object} options - Animation options
 */
export const animateText = (element, options = {}) => {
  if (!element) return;

  const defaults = {
    minDelay: 0.02,        // Minimum delay between characters (seconds)
    maxDelay: 0.15,        // Maximum delay between characters (seconds)
    lineDelay: 0.3,        // Additional delay for new lines
    flickerProbability: 0.08, // Probability of a character flickering
    glowProbability: 0.05,    // Probability of a character glowing
    excludeSelectors: ['a', 'button', 'input', '.count', '.no-animate'] // Elements to exclude
  };

  const settings = { ...defaults, ...options };

  // Skip elements that should be excluded
  if (settings.excludeSelectors.some(selector => element.matches(selector))) {
    return;
  }

  // Get original text content
  const originalText = element.textContent;
  element.classList.add('text-animate-container');

  // Clear the element
  element.textContent = '';

  // Add each character with random delays
  let cumulativeDelay = 0;
  let isPreviousNewline = false;

  [...originalText].forEach(char => {
    const charSpan = document.createElement('span');
    charSpan.textContent = char;
    charSpan.classList.add('text-animate-char');

    // Add special line delay if starting a new line
    if (isPreviousNewline) {
      cumulativeDelay += settings.lineDelay;
      isPreviousNewline = false;
    }

    // Get random delay for this character
    const thisDelay = getRandomDelay(settings.minDelay, settings.maxDelay);
    cumulativeDelay += thisDelay;

    // Apply the delay
    charSpan.style.animationDelay = `${cumulativeDelay}s`;

    // Add special effects to some characters
    if (shouldApplyEffect(settings.flickerProbability)) {
      charSpan.classList.add('text-animate-flicker');
    }

    if (shouldApplyEffect(settings.glowProbability)) {
      charSpan.classList.add('text-animate-glow');
    }

    // Check if character is a newline
    if (char === '\n') {
      isPreviousNewline = true;
      element.appendChild(document.createElement('br'));
    } else {
      element.appendChild(charSpan);
    }
  });

  return cumulativeDelay; // Return total animation duration
};

/**
 * Process a container and animate all text nodes within it
 * @param {HTMLElement} container - Container element
 * @param {Object} options - Animation options
 */
export const animateTextInContainer = (container, options = {}) => {
  if (!container) return;

  // Get all text nodes that aren't inside excluded elements
  const walker = document.createTreeWalker(
    container,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode: function(node) {
        // Skip empty text nodes or those in excluded elements
        if (node.textContent.trim() === '') return NodeFilter.FILTER_REJECT;

        const parent = node.parentNode;
        const excluded = options.excludeSelectors || ['a', 'button', 'input', '.count', '.no-animate'];

        // Check if parent matches any excluded selector
        if (excluded.some(selector => parent.matches(selector))) {
          return NodeFilter.FILTER_REJECT;
        }

        return NodeFilter.FILTER_ACCEPT;
      }
    }
  );

  // Process each text node
  const textNodes = [];
  let currentNode;
  while (currentNode = walker.nextNode()) {
    textNodes.push(currentNode);
  }

  // Animate each text node
  textNodes.forEach(textNode => {
    const originalText = textNode.textContent;
    const span = document.createElement('span');
    textNode.parentNode.replaceChild(span, textNode);
    span.textContent = originalText;
    animateText(span, options);
  });
};

export default { animateText, animateTextInContainer };
